import z from '@deepseek-ai/schemastery';
export const Config=z.object({feedbackEnabled:z.boolean().default(false).volatile()});
export const name='natural-work-brand';
export function apply(ctx){
  ctx.inject(["settings"], child=>child.effect(()=>child.settings.configure({auto:false},ctx.fiber)));
  // Older persisted presets contain {{cwd}}. Keep them usable after the 0.2.1
  // migration, resolving the value from the host's current session directory.
  ctx.inject(['systemPrompt','workingDirectory'], scope => {
    scope.systemPrompt.variable('cwd', context => context.agent
      ? scope.workingDirectory.get(context.agent.session)
      : scope.workingDirectory.defaultDirectory);
  });
}
